    /// <summary>The table, built once from the two lists above (declared before it, so they are set first).</summary>
    internal static readonly FrozenDictionary<int, string> Table = Build();

    static FrozenDictionary<int, string> Build()
    {
        var table = new Dictionary<int, string>();
        foreach (var (first, last, ascii, step) in Runs)
            for (var cp = first; cp <= last; cp++)
                table.Add(cp, ((char)(ascii + step * (cp - first))).ToString());
        foreach (var (cp, ascii) in Singles) table.Add(cp, ascii);
        return table.ToFrozenDictionary();
    }
